// Growthic One — Edge Function: event-announcements
// Fired by a database trigger when HR schedules a company event. Emails every
// active employee their own copy (greeting by first name). One email per
// event, ever (event_email_log). Events that already ended are skipped.
//
// Required env vars:
//   RESEND_API_KEY, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
//   EVENT_WEBHOOK_SECRET — must match the x-webhook-secret header the trigger sends
//
// Test mode (no log, one email only):
//   POST { "test_to": "you@example.com", "test_name": "Sunil" }

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const FROM_ADDRESS = 'Growthic One <noreply@thegrowthic.com>'
const APP_URL      = 'https://one.thegrowthic.com/home'
const JSON_HEADERS = { 'Content-Type': 'application/json' }
// Public link to the hero image (served by this function, see the GET route below).
// Bump ?v= when the image changes so mail apps fetch the new one.
const HERO_URL     = 'https://sagqqcctagolalfrezwg.supabase.co/functions/v1/event-announcements/hero.jpg?v=1'

type EventRow = {
  id?: string
  title: string
  description: string | null
  start_date: string
  end_date: string
  duration_type: string | null
  start_time: string | null
  end_time: string | null
  location: string | null
  created_by_emp?: { name?: string } | null
}

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

// IST has no DST, so a fixed +05:30 offset is exact.
function todayISTString(): string {
  const now = new Date(Date.now() + 5.5 * 3600 * 1000)
  return now.toISOString().slice(0, 10)
}

function fmtDay(iso: string): string {
  const d = new Date(`${iso}T00:00:00Z`)
  return d.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' })
}

function fmtRange(start: string, end: string): string {
  return start === end ? fmtDay(start) : `${fmtDay(start)} – ${fmtDay(end)}`
}

function hhmm(t: string | null): string {
  return t ? t.slice(0, 5) : ''
}

function timeText(ev: EventRow): string {
  switch (ev.duration_type) {
    case 'first_half':  return 'First half of the day'
    case 'second_half': return 'Second half of the day'
    case 'specific_time':
      return ev.start_time && ev.end_time ? `${hhmm(ev.start_time)} – ${hhmm(ev.end_time)}` : 'Specific time'
    default:            return 'All day'
  }
}

function ymd(iso: string): string { return iso.replace(/-/g, '') }

function plusOneDay(iso: string): string {
  const d = new Date(`${iso}T00:00:00Z`)
  d.setUTCDate(d.getUTCDate() + 1)
  return d.toISOString().slice(0, 10)
}

function googleCalendarUrl(ev: EventRow): string {
  let dates: string
  if (ev.duration_type === 'specific_time' && ev.start_time && ev.end_time) {
    dates = `${ymd(ev.start_date)}T${hhmm(ev.start_time).replace(':', '')}00/${ymd(ev.end_date)}T${hhmm(ev.end_time).replace(':', '')}00`
  } else {
    dates = `${ymd(ev.start_date)}/${ymd(plusOneDay(ev.end_date))}`
  }
  const q = new URLSearchParams({ action: 'TEMPLATE', text: ev.title, dates, ctz: 'Asia/Kolkata' })
  if (ev.location)    q.set('location', ev.location)
  if (ev.description) q.set('details', ev.description)
  return `https://calendar.google.com/calendar/render?${q.toString()}`
}

function detailRow(icon: string, text: string): string {
  return `<tr>
              <td width="30" valign="top" style="font-size:16px;line-height:1.5;padding:4px 0;">${icon}</td>
              <td valign="top" style="font-size:15px;line-height:1.5;color:#111827;padding:4px 0;">${text}</td>
            </tr>`
}

function buildHtml(firstName: string, ev: EventRow): string {
  const rows = [
    detailRow('&#128197;', `<strong>${escapeHtml(fmtRange(ev.start_date, ev.end_date))}</strong>`),
    detailRow('&#128339;', escapeHtml(timeText(ev))),
    ev.location ? detailRow('&#128205;', escapeHtml(ev.location)) : '',
  ].join('')
  const description = ev.description
    ? `<p style="margin:14px 0 0;font-size:14px;line-height:1.7;color:#374151;white-space:pre-line;">${escapeHtml(ev.description)}</p>`
    : ''
  const addedBy = ev.created_by_emp?.name
    ? `<p style="margin:14px 0 0;font-size:12px;color:#8A94A8;">Added by ${escapeHtml(ev.created_by_emp.name)}</p>`
    : ''

  return `<!doctype html>
<html>
<body style="margin:0;padding:0;background:#EEF3FA;font-family:Arial,Helvetica,sans-serif;color:#111827;">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(ev.title)} on ${escapeHtml(fmtRange(ev.start_date, ev.end_date))}. Add it to your calendar.</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF3FA;">
    <tr><td align="center" style="padding:24px 12px;">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;">

        <!-- Hero (served by this function, includes the Growthic One logo) -->
        <tr><td style="font-size:0;line-height:0;background:#1A72C7;">
          <img src="${HERO_URL}" alt="Growthic One: heads up, team! There's a new event scheduled" width="600" style="display:block;width:100%;max-width:600px;height:auto;border:0;">
        </td></tr>

        <!-- Greeting -->
        <tr><td style="padding:28px 32px 8px;font-size:16px;line-height:1.75;color:#111827;background:#ffffff;">
          <p style="margin:0 0 6px;">Hi ${escapeHtml(firstName)},</p>
          <p style="margin:0;">A new event has just been added to the Growthic One calendar.</p>
        </td></tr>

        <!-- Event card -->
        <tr><td style="padding:16px 32px 8px;background:#ffffff;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F7FF;border-radius:14px;">
            <tr><td style="padding:22px 24px;">
              <div style="font-size:22px;font-weight:800;line-height:1.3;color:#0F4799;padding-bottom:10px;">${escapeHtml(ev.title)}</div>
              <table role="presentation" cellpadding="0" cellspacing="0">${rows}</table>
              ${description}
              ${addedBy}
            </td></tr>
          </table>
        </td></tr>

        <!-- Buttons -->
        <tr><td align="center" style="padding:20px 32px 8px;background:#ffffff;">
          <table role="presentation" cellpadding="0" cellspacing="0"><tr>
            <td style="background:#0F4799;border-radius:8px;">
              <a href="${APP_URL}" style="display:inline-block;padding:12px 26px;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;">View in Growthic One</a>
            </td>
          </tr></table>
          <p style="margin:14px 0 0;font-size:13px;"><a href="${escapeHtml(googleCalendarUrl(ev))}" style="color:#1A72C7;text-decoration:underline;">Add to Google Calendar</a></p>
        </td></tr>

        <!-- Emoji row -->
        <tr><td align="center" style="padding:14px 24px 28px;background:#ffffff;font-size:30px;line-height:1.2;letter-spacing:12px;">
          &#128197;&#127881;&#129395;
        </td></tr>

        <!-- Footer: one slim line -->
        <tr><td align="center" style="padding:11px 16px;background:#0F4799;font-size:11px;line-height:1.4;color:#BFD4F2;">
          Growthic One &nbsp;&middot;&nbsp; Automated notification, please don't reply
        </td></tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`
}

function mailFor(firstName: string, to: string, ev: EventRow) {
  return {
    from: FROM_ADDRESS,
    to: [to],
    subject: `New event: ${ev.title} (${fmtRange(ev.start_date, ev.end_date)})`,
    html: buildHtml(firstName, ev),
    headers: { 'Reply-To': 'noreply@thegrowthic.com', 'Auto-Submitted': 'auto-generated' },
  }
}

Deno.serve(async (req: Request) => {
  // Public image route used by the email's <img>. Serves the hero JPEG, nothing else.
  if (req.method === 'GET' && new URL(req.url).pathname.endsWith('/hero.jpg')) {
    const bytes = Uint8Array.from(atob(HERO_B64), (c) => c.charCodeAt(0))
    return new Response(bytes, {
      headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400' },
    })
  }

  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405 })

  const expected = Deno.env.get('EVENT_WEBHOOK_SECRET')
  if (!expected || req.headers.get('x-webhook-secret') !== expected) {
    return new Response(JSON.stringify({ error: 'unauthorized' }), { status: 401, headers: JSON_HEADERS })
  }

  const RESEND_API_KEY = Deno.env.get('RESEND_API_KEY')
  if (!RESEND_API_KEY) {
    return new Response(JSON.stringify({ error: 'RESEND_API_KEY not configured' }), { status: 500, headers: JSON_HEADERS })
  }

  const body = await req.json().catch(() => ({}))
  const resendHeaders = { 'Authorization': `Bearer ${RESEND_API_KEY}`, ...JSON_HEADERS }

  // Test mode: one sample to one address. No database access, nothing logged.
  if (body.test_to) {
    const start = todayISTString()
    const sample: EventRow = {
      title: body.test_title || 'Quarterly Team Offsite',
      description: 'A relaxed day together: lunch, a few short talks and a team quiz. Please keep the day free.',
      start_date: start,
      end_date: start,
      duration_type: 'full_day',
      start_time: null,
      end_time: null,
      location: 'Office Lounge',
      created_by_emp: { name: 'Yugansh Chokra' },
    }
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST', headers: resendHeaders,
      body: JSON.stringify(mailFor(body.test_name || 'Sunil', body.test_to, sample)),
    })
    const data = await res.json().catch(() => ({}))
    return new Response(JSON.stringify({ test: true, sent: res.ok, result: data }), { headers: JSON_HEADERS })
  }

  if (!body.event_id) {
    return new Response(JSON.stringify({ error: 'event_id required' }), { status: 400, headers: JSON_HEADERS })
  }

  try {
    const supabase = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)

    const { data: ev, error: evErr } = await supabase
      .from('company_events')
      .select('id, title, description, start_date, end_date, duration_type, start_time, end_time, location, created_by_emp:employees!created_by(name)')
      .eq('id', body.event_id)
      .single()
    if (evErr || !ev) {
      return new Response(JSON.stringify({ error: 'event not found' }), { status: 404, headers: JSON_HEADERS })
    }
    const event = ev as unknown as EventRow

    // An event that already ended (HR recording something past) gets no email.
    const lastDay = event.end_date || event.start_date
    if (lastDay < todayISTString()) {
      return new Response(JSON.stringify({ skipped: 'event already ended' }), { headers: JSON_HEADERS })
    }

    // One email per event, ever. The primary key makes this check race-proof.
    const { error: logErr } = await supabase.from('event_email_log').insert({ event_id: event.id })
    if (logErr) {
      if (logErr.code === '23505') {
        return new Response(JSON.stringify({ skipped: 'already sent' }), { headers: JSON_HEADERS })
      }
      throw logErr
    }

    const { data: employees, error: empErr } = await supabase
      .from('employees').select('name, email').eq('status', 'active')
    if (empErr) throw empErr
    const recipients = (employees || []).filter((e) => e.email)

    const payload = recipients.map((e) => mailFor((e.name || 'there').split(' ')[0], e.email, event))
    let sent = 0
    let failed: unknown = null
    for (let i = 0; i < payload.length; i += 100) {
      const res = await fetch('https://api.resend.com/emails/batch', {
        method: 'POST',
        headers: { ...resendHeaders, 'Idempotency-Key': `event-announcement-${event.id}-${i}` },
        body: JSON.stringify(payload.slice(i, i + 100)),
      })
      if (res.ok) {
        sent += Math.min(100, payload.length - i)
      } else {
        failed = await res.json().catch(() => ({}))
        console.error('[event-announcements] Resend batch error:', failed)
        break
      }
    }

    if (failed) {
      // Allow a retry later if nothing at all went out.
      if (sent === 0) await supabase.from('event_email_log').delete().eq('event_id', event.id)
      return new Response(JSON.stringify({ sent, error: failed }), { status: 502, headers: JSON_HEADERS })
    }

    await supabase.from('event_email_log').update({ recipients: sent }).eq('event_id', event.id)
    return new Response(JSON.stringify({ event: event.title, sent }), { headers: JSON_HEADERS })
  } catch (err) {
    console.error('[event-announcements] fatal:', err)
    return new Response(JSON.stringify({ error: String(err) }), { status: 500, headers: JSON_HEADERS })
  }
})

// Hero banner (includes the Growthic One logo), served at HERO_URL (JPEG, base64).
const HERO_B64 =
  ''
